"""Local, read-only VMware access check. Credentials are prompted, never persisted."""
import argparse
import ctypes as c
import getpass
import json
from pathlib import Path
import sys
import time

DLL = r"C:\Program Files\VMware\VMware Workstation\vix.dll"
VMX = r"D:\07_Virtual_Machines\VmSimNodus\VmSimNodus.vmx"
RESULT = Path(__file__).with_name("sn021-vm-access-result.json")


class Vix:
    def __init__(self):
        self.d = c.CDLL(DLL)
        signatures = {
            "VixHost_Connect": (c.c_int, [c.c_int,c.c_int,c.c_char_p,c.c_int,c.c_char_p,c.c_char_p,c.c_int,c.c_int,c.c_void_p,c.c_void_p]),
            "VixHost_OpenVM": (c.c_int, [c.c_int,c.c_char_p,c.c_int,c.c_int,c.c_void_p,c.c_void_p]),
            "VixVM_WaitForToolsInGuest": (c.c_int, [c.c_int,c.c_int,c.c_void_p,c.c_void_p]),
            "VixVM_LoginInGuest": (c.c_int, [c.c_int,c.c_char_p,c.c_char_p,c.c_int,c.c_void_p,c.c_void_p]),
            "VixVM_LogoutFromGuest": (c.c_int, [c.c_int,c.c_void_p,c.c_void_p]),
            "Vix_ReleaseHandle": (None, [c.c_int]),
            "VixHost_Disconnect": (None, [c.c_int]),
            "VixJob_CheckCompletion": (c.c_uint64, [c.c_int,c.POINTER(c.c_int)]),
        }
        for name,(ret,args) in signatures.items():
            f=getattr(self.d,name);f.restype=ret;f.argtypes=args
        self.d.VixJob_Wait.restype=c.c_uint64
        self.d.VixJob_Wait.argtypes=[c.c_int,c.c_int]
        self.d.VixPropertyList_AllocPropertyList.restype=c.c_uint64
        self.d.VixPropertyList_AllocPropertyList.argtypes=[c.c_int,c.POINTER(c.c_int),c.c_int]

    def job(self, handle, result_handle=False):
        try:
            deadline=time.monotonic()+45
            while True:
                complete=c.c_int()
                error=self.d.VixJob_CheckCompletion(handle,c.byref(complete))
                if error:raise RuntimeError("VIX error " + str(error))
                if complete.value:break
                if time.monotonic()>deadline:raise RuntimeError("VIX operation timed out")
                time.sleep(0.1)
            result=c.c_int()
            if result_handle:
                error=self.d.VixJob_Wait(handle,3010,c.byref(result),c.c_int(0))
            else:error=self.d.VixJob_Wait(handle,0)
            if error:raise RuntimeError("VIX error " + str(error))
            return result.value
        finally:self.d.Vix_ReleaseHandle(handle)


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--preflight',action='store_true')
    args=parser.parse_args()
    if not args.preflight and not sys.stdin.isatty():
        raise SystemExit('Run this script in an interactive host terminal; no redirected passwords.')
    report={'status':'started','stage':'connect','guest_mutation':False}
    api=Vix();host=vm=properties=0;logged=False
    try:
        host=api.job(api.d.VixHost_Connect(-1,3,None,0,None,None,0,0,None,None),True)
        if args.preflight:
            print('Installed VIX library loaded and local Workstation connection verified. No credentials used.')
            return
        report['stage']='open encrypted VM'
        secret=getpass.getpass('VMware encryption password (hidden): ').encode('utf-8')
        prop=c.c_int()
        error=api.d.VixPropertyList_AllocPropertyList(host,c.byref(prop),7001,c.c_char_p(secret),c.c_int(0))
        del secret
        if error:raise RuntimeError('VIX property error '+str(error))
        properties=prop.value
        vm=api.job(api.d.VixHost_OpenVM(host,VMX.encode(),0,properties,None,None),True)
        api.d.Vix_ReleaseHandle(properties);properties=0
        report['stage']='VMware Tools'
        api.job(api.d.VixVM_WaitForToolsInGuest(vm,30,None,None))
        report['stage']='guest login'
        guest=getpass.getpass('Windows guest password for SimNodus (hidden): ').encode('utf-8')
        pending=api.d.VixVM_LoginInGuest(vm,b'SimNodus',guest,0,None,None)
        del guest
        api.job(pending);logged=True
        report.update(status='verified-access-only',stage='complete')
    except Exception as error:
        report.update(status='failed',error_type=type(error).__name__)
        # Only emit our numeric/sanitized VIX errors, never arbitrary exception data.
        if isinstance(error,RuntimeError):report['error']=str(error)
    finally:
        if logged:
            try:api.job(api.d.VixVM_LogoutFromGuest(vm,None,None))
            except Exception:report['logout_failed']=True
        if properties:api.d.Vix_ReleaseHandle(properties)
        if vm:api.d.Vix_ReleaseHandle(vm)
        if host:api.d.VixHost_Disconnect(host)
        if not args.preflight:
            RESULT.write_bytes((json.dumps(report,indent=2)+'\n').encode())
            print(json.dumps(report))
            print('Only a credential-free access result was saved. No guest commands ran.')


if __name__=='__main__':main()

