        const ManagedId& run, const ManagedCommitRequest& request);
private:
    struct Impl;
    explicit ManagedStore(std::unique_ptr<Impl> impl);
    std::unique_ptr<Impl> impl_;
    friend ManagedStoreOpen open_managed_store(const std::string&);
};
