        $script:counter++;$directory=@{a='admin';w='writer';c='client'}[$Role]
        $output="$harness\$directory\$($script:counter)-$Label.jsonl";$errors="$output.stderr"
        $nativeArguments=@('--report',$output)+$Arguments
